	[ 'eans' => [ '7318841761442' ], 'html' => '<p>Sort udgave af Haglöfs Fjatla 40, en enkel duffelbag på 40 liter i let, komprimerbart og meget slidstærkt stof, der kan pakkes sammen, når den ikke er i brug. Den lave vægt gør den oplagt som taske til rejser og weekendture, hvor den bliver kastet rundt.</p><ul><li>40 liter</li><li>Let og komprimerbar</li><li>Farve: sort</li></ul>' ],
