	[ 'eans' => [ '1213000558207' ], 'html' => '<p>Reparationssæt fra Therm-a-Rest til underlag med den klassiske ventil. Er ventilen blevet utæt, beskadiget eller slidt, kan sættet give underlaget nyt liv, så det ikke skal kasseres.</p>' ],
