	[ 'eans' => [ '1213000736353' ], 'html' => '<p>Liv Cropped Pants er en kort, let damebuks i Didriksons\' StretchLite, en smidig mikrofibernylon, der strækker sig med dine bevægelser. Den kropsnære pasform gør den alsidig til tur og hverdag.</p><ul><li>StretchLite-materiale</li><li>Farve: sort</li><li>Str. 34</li></ul>' ],
