	[ 'eans' => [ '7333371395080' ], 'html' => '<p>Let børnehue fra Didriksons, der sidder godt på hovedet i de kølige måneder fra efterår til tidligt forår. Stoffet er en funktionel blanding, der føles blød mod huden.</p><ul><li>50 % viskose, 28 % polyamid, 22 % polyester</li><li>Juniorstørrelse</li><li>Farve: orange</li></ul>' ],
