	[ 'eans' => [ '0671227916605', '0671227916681', '0671227916568', '0671227916674', '0671227916599', '0671227916650', '0671227916612', '0671227916643', '0671227916667', '4752078101108' ], 'html' => '<p>Flexitubes er rørene i Pro Sportfishers system til rørfluer. Du sætter den størrelse tube eller vægt på, du har brug for, hvilket giver mange muligheder, når du binder.</p><ul><li>Størrelse 40/10</li><li>Del af Pro rørfluesystemet</li></ul>' ],
