	[ 'eans' => [ '7318841954219' ], 'html' => '<p>Beige duffelbag fra Haglöfs, der tager funktionerne fra Tight-rygsækkene med over i et taskeformat til rejser, weekender, træning og transport af grej. 50 liter giver plads til tøj, sko og udstyr til flere dage.</p><ul><li>50 liter</li><li>Bygger på Tight-serien</li><li>Farve: beige</li></ul>' ],
